// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint256 timestamp) public {
        vm.assume(blockNum % 15 == 0);
        vm.assume(timestamp > 0);
        vm.assume(timestamp > 0);
        vm.roll(blockNum);
        vm.warp(timestamp);

        address caller = address(0xdead);
        vm.deal(caller, 10 ether);

        uint256 callerBalBefore = caller.balance;
        uint256 contractBalBefore = address(c).balance;
        uint256 sumBefore = callerBalBefore + contractBalBefore;

        vm.prank(caller);
        (bool success,) = address(c).call{value: 10 ether}("");
        require(success, "call failed");

        uint256 callerBalAfter = caller.balance;
        uint256 contractBalAfter = address(c).balance;
        uint256 sumAfter = callerBalAfter + contractBalAfter;

        assertTrue(sumAfter == sumBefore);
    }
}
